{
  "context": {
    "action": "search",
    "bap_id": "{{ondc_bap_id}}",
    "bap_uri": "{{mockServerUrl}}/workbench-bap",
    "domain": "ONDC:TRV10",
    "location": {
      "city": {
        "code": "{{ondc_city_code}}"
      },
      "country": {
        "code": "IND"
      }
    },
    "message_id": "{{ondc_message_id}}",
    "timestamp": "{{ondc_timestamp}}",
    "transaction_id": "{{ondc_txn_id}}",
    "ttl": "PT30S",
    "version": "2.1.0"
  },
  "message": {
    "intent": {
      "category": {
        "descriptor": {
          "code": "SCHEDULED_TRIP"
        }
      },
      "fulfillment": {
        "stops": [
          {
            "location": {
              "address": "Connaught Place, New Delhi",
              "area_code": "110001",
              "city": {
                "code": "{{ondc_city_code}}"
              },
              "country": {
                "code": "IND"
              },
              "district": "New Delhi",
              "gps": "{{origin_lat}},{{origin_lon}}"
            },
            "type": "START",
            "time": {
              "timestamp": "{{ondc_pickup_time}}"
            }
          },
          {
            "location": {
              "address": "{{drop_address}}",
              "area_code": "110001",
              "city": {
                "code": "{{ondc_city_code}}"
              },
              "country": {
                "code": "IND"
              },
              "district": "New Delhi",
              "gps": "{{drop_lat}},{{drop_lon}}"
            },
            "type": "END"
          }
        ]
      },
      "payment": {
        "collected_by": "{{payment_collected_by}}"
      },
      "tags": [
        {
          "descriptor": {
            "code": "BAP_TERMS",
            "name": "BAP Terms of Engagement"
          },
          "display": false,
          "list": [
            {
              "descriptor": {
                "code": "BUYER_FINDER_FEES_PERCENTAGE"
              },
              "value": "1"
            },
            {
              "descriptor": {
                "code": "DELAY_INTEREST"
              },
              "value": "5"
            },
            {
              "descriptor": {
                "code": "STATIC_TERMS"
              },
              "value": "https://example-test-bap.com/static-terms.txt"
            }
          ]
        }
      ]
    }
  }
}

